\begin{itemize}
\item[(a)] \(\quad g(-1)=\int_{0}^{-1} f(t) d t=-\int_{-1}^{0} f(t) d t=-\frac{3}{2}\) \(g^{\prime}(-1)=f(-1)=0\) \(g^{\prime \prime}(-1)=f^{\prime}(-1)=3\)
\end{itemize}
\[
3 \begin{cases}1: & g(-1) \\ 1: & g^{\prime}(-1) \\ 1: & g^{\prime \prime}(-1)\end{cases}
\]
\begin{itemize}
\item[(b)] \(g\) is increasing on \(-1<x<1\) because \(g^{\prime}(x)=f(x)>0\) on this interval.
\end{itemize}
\[
2 \begin{cases}1 & : \text { interval } \\ 1 & : \text { reason }\end{cases}
\]
\begin{itemize}
\item[(c)] The graph of \(g\) is concave down on \(0<x<2\) because \(g^{\prime \prime}(x)=f^{\prime}(x)<0\) on this interval. or because \(g^{\prime}(x)=f(x)\) is decreasing on this interval.
\end{itemize}
\[
2 \begin{cases}1: & \text { interval } \\ 1: & \text { reason }\end{cases}
\]
